import { beforeEach, describe, expect, test, vi } from "vitest";

/**
 * IMEで打った読みを設定資料へ効かせる（設計書6.42.2。作者の裁定、2026-10-24）。
 *
 * 確かめるのは、裁定の分かれ目が**実際の保存の口**でどう動くか——
 *
 * - AIが作った項目で読みが空 → 保存の口（人物は `saveOrUpdate`、ほかは `saveAll`）で埋める。
 *   **`autoGenerated` は true のまま**（機械が埋めた読みに作者の印を付けない）
 * - 作者が作った項目・別の読みが入っている項目 → 書かない
 * - 別名で当たった読みは、項目の読み（名前の読み）にしない
 */

interface Item {
  id: string;
  name: string;
  aliases: string[];
  reading: string | null;
  autoGenerated: boolean;
  updatedAt: string;
}

const characters: Item[] = [];
const locations: Item[] = [];
const saved: Array<{ via: string; record: Item }> = [];
let imeFile = { version: 1 as const, entries: [] as unknown[] };

vi.mock("../../../src/core/characterStore", () => ({
  CharacterStore: class {
    private loaded = false;
    async loadAll() {
      this.loaded = true;
      return { characters: characters.map((item) => ({ ...item })), errors: [] };
    }
    async saveOrUpdate(record: Item) {
      // 本物は読み込んだ控えが無いと「新規作成」に落ちて既存のファイルで失敗する
      if (!this.loaded) throw new Error("loadAll を済ませずに保存した");
      saved.push({ via: "saveOrUpdate", record });
    }
  },
}));

function settingsStore(source: Item[], name: string) {
  return {
    loadAll: async () => ({ records: source.map((item) => ({ ...item })), errors: [] }),
    saveAll: async (records: Item[]) => {
      for (const record of records) saved.push({ via: `${name}.saveAll`, record });
    },
  };
}

vi.mock("../../../src/core/abilityStore", () => ({
  createAbilityStore: () => settingsStore([], "ability"),
  createOrganizationStore: () => settingsStore([], "organization"),
  createLocationStore: () => settingsStore(locations, "location"),
  createWorldStore: () => settingsStore([], "world"),
}));

vi.mock("../../../src/core/imeReadingStore", () => ({
  loadImeReadings: async () => ({ file: imeFile, hash: undefined }),
  updateImeReadings: async (_work: unknown, change: (file: typeof imeFile) => typeof imeFile) => {
    imeFile = change(imeFile);
    return imeFile;
  },
}));

import {
  imeNameReadingSpans,
  invalidateImeNameCache,
  recordImeComposition,
} from "../../../src/features/imeReadings";
import type { WorkEntry } from "../../../src/models/types";

const work = { id: "w1", folderPath: "/w" } as WorkEntry;

function item(id: string, name: string, extra: Partial<Item> = {}): Item {
  return {
    id,
    name,
    aliases: [],
    reading: null,
    autoGenerated: true,
    updatedAt: "2026-10-01T00:00:00Z",
    ...extra,
  };
}

beforeEach(() => {
  characters.length = 0;
  locations.length = 0;
  saved.length = 0;
  imeFile = { version: 1, entries: [] };
  invalidateImeNameCache();
});

describe("設定資料へ書く／書かない", () => {
  test("AIが作った人物で読みが空なら、saveOrUpdate で埋める（autoGenerated は true のまま）", async () => {
    characters.push(item("char_1", "東雲"));
    const result = await recordImeComposition(work, "しののめは", "東雲は");
    expect(result.capture).toEqual({ surface: "東雲", reading: "しののめ" });
    expect(result.filled).toEqual([{ kind: "character", id: "char_1", name: "東雲" }]);
    expect(saved).toHaveLength(1);
    expect(saved[0].via).toBe("saveOrUpdate");
    expect(saved[0].record.reading).toBe("しののめ");
    expect(saved[0].record.autoGenerated).toBe(true);
  });

  test("場所は saveAll で埋める", async () => {
    locations.push(item("loc_1", "霧ヶ峰"));
    await recordImeComposition(work, "きりがみね", "霧ヶ峰");
    expect(saved.map((entry) => entry.via)).toEqual(["location.saveAll"]);
  });

  test("作者が作った項目には書かない（控えには残る）", async () => {
    characters.push(item("char_1", "東雲", { autoGenerated: false }));
    const result = await recordImeComposition(work, "しののめ", "東雲");
    expect(result.filled).toEqual([]);
    expect(saved).toEqual([]);
    expect(imeFile.entries).toHaveLength(1);
  });

  test("別の読みが入っていれば書かない", async () => {
    characters.push(item("char_1", "東雲", { reading: "とううん" }));
    await recordImeComposition(work, "しののめ", "東雲");
    expect(saved).toEqual([]);
  });

  test("別名で当たった読みは、項目の読みにしない", async () => {
    characters.push(item("char_1", "灯", { aliases: ["姫君"] }));
    const result = await recordImeComposition(work, "ひめぎみ", "姫君");
    expect(result.capture).toEqual({ surface: "姫君", reading: "ひめぎみ" });
    expect(saved).toEqual([]);
  });

  test("名前に当たらない変換は控えにも残さない", async () => {
    characters.push(item("char_1", "東雲"));
    await recordImeComposition(work, "かわ", "川");
    expect(imeFile.entries).toEqual([]);
    expect(saved).toEqual([]);
  });
});

describe("読み上げの範囲", () => {
  test("設定資料の読みが勝ち、空ならIMEの控えを使う", async () => {
    characters.push(item("char_1", "東雲", { reading: "しののめ" }));
    characters.push(item("char_2", "白樺", { autoGenerated: false }));
    imeFile = {
      version: 1,
      entries: [
        { surface: "東雲", reading: "しの", count: 9, lastSeen: "2026-10-24T00:00:00Z" },
        { surface: "白樺", reading: "しらかば", count: 1, lastSeen: "2026-10-24T00:00:00Z" },
      ],
    };
    const text = "東雲と白樺。";
    const { spans } = await imeNameReadingSpans(work, text);
    expect(spans).toEqual([
      { start: 0, end: 2, reading: "しののめ" },
      { start: 3, end: 5, reading: "しらかば" },
    ]);
  });
});
